const byId = new Map<number, ItemDef>();
const byCode = new Map<number, ItemDef>();
for (const d of ITEM_DEFS) { byId.set(d.id, d); byCode.set(d.code, d); }
export function itemDefById(id: number): ItemDef | undefined { return byId.get(id); }
export function itemDefByCode(code: number): ItemDef | undefined { return byCode.get(code); }
export function itemIconUrl(d: ItemDef): string { return `/res/image/sinimage/items/${d.folder}/it${d.icon}.bmp`; }
